  "{0}: нет .TBL — только потоки, калибровка counts недоступна": { en: "{0}: no .TBL — streams only, counts calibration unavailable", zh: "{0}: 无 .TBL — 仅数据流，counts 标定不可用", ja: "{0}: .TBL なし — ストリームのみ、counts 校正不可" },
